import { Injectable } from "@angular/core";
import { FormGroup } from "@angular/forms";
import { NewCard } from "src/app/models/card/new-card.model";
import { ImagesService } from "../external/images/images.service";
import { PexelsResponse } from "src/app/models/pexels/pexels-response.model";

@Injectable({
    providedIn: 'root'
  })
  export class CardUtils {

    constructor(private image: ImagesService){

    }

    public createNewCard(form: FormGroup): NewCard {
        const newCard = new NewCard();
        newCard.title = form.value.titulo;
        newCard.description = form.value.descricao;

        return newCard;
    }

    public sortImages(): string{
        const pagina = this.getRandomNumber(1, 10);
        const imagem = this.getRandomNumber(1, 15);

        let result = this.image.getHappyImagesPexels(pagina).subscribe({
            next: (response: PexelsResponse) => {
                return response.photos[imagem].src.large;
            },
            error: (err) {
                console.log(err);
            }
        });

        if (result.photos && result.photos.length > 0) {
            // Retornar a URL da imagem aleatória
            return result.photos[imagem].src.large;
          } else {
            return ''; // Ou algum valor padrão caso não haja fotos
          }
          return result.photos[imagem].src.large;
    }

    public getRandomNumber(min: number, max: number): number {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    // public imageSorted(): string{
    //     return 
    // }
  }
